mapper.select:
SELECT FROM product_attribute_group WHERE delete_flag = '0'
AND name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY sort, id LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM product_attribute_group
WHERE delete_flag = '0'
  AND name = #{name}

    AND id != #{excludeId}

SELECT v.id, v.group_id, v.value, v.sort, v.enabled, v.delete_flag, v.deleted_token, v.created_by, v.updated_by, v.create_time, v.update_time FROM product_attribute_value v WHERE v.delete_flag = '0'
AND v.group_id = #{groupId}
AND v.value LIKE CONCAT('%', #{keyword}, '%')
ORDER BY v.group_id, v.sort, v.id LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM product_attribute_value v WHERE v.delete_flag = '0'
AND v.group_id = #{groupId}
AND v.value LIKE CONCAT('%', #{keyword}, '%')

SELECT COUNT(*)
FROM product_attribute_value
WHERE delete_flag = '0'
  AND group_id = #{groupId}
  AND value = #{value}

    AND id != #{excludeId}

mapper.update:
UPDATE product_attribute_value
SET enabled     = #{enabled},
    updated_by  = #{updatedBy},
    update_time = #{updateTime}
WHERE id = #{id}
  AND delete_flag = '0'
